import ArrowBackIcon from '@material-ui/icons/ArrowBack'
import EntryLinks from '../EntryLinks/EntryLinks'
import { BlockMarkdown, InlineMarkdown } from '../Markdown/Markdown'
import { TagLinks } from '../Tags/Tags'
import { posts } from '../../generated/projects'
import './ProjectDetail.css'

// 글 끝에서 이웃 글로 이어 준다. 목록으로 돌아가야만 다음 글을 찾을 수 있으면
// 읽기가 글 하나에서 끊긴다 — 블로그는 글에서 글로 흘러야 한다.
const adjacentPosts = (slug) => {
  const index = posts.findIndex((post) => post.slug === slug)

  if (index < 0) return { prev: null, next: null }
  return {
    prev: index > 0 ? posts[index - 1] : null,
    next: index < posts.length - 1 ? posts[index + 1] : null,
  }
}

// 글과 이력이 같은 상세 화면을 쓴다. 돌아가는 곳만 다르다.
// backTo 가 오면(포트폴리오에서 들어온 경우) 그쪽을 우선한다 —
// 들어온 문으로 나가는 것이 자연스럽다.
const ProjectDetail = ({ project, backTo }) => {
  if (!project) {
    return (
      <section className='project-detail project-detail--missing'>
        <h1>찾을 수 없는 문서입니다.</h1>
        <a href='#work' className='link project-detail__back'>
          이력으로 돌아가기
        </a>
      </section>
    )
  }

  const isPost = project.type === 'post'
  const back =
    backTo ||
    (isPost
      ? { href: '#/blog', label: '글 목록' }
      : { href: '#work', label: '이력으로' })
  const { prev, next } = isPost
    ? adjacentPosts(project.slug)
    : { prev: null, next: null }

  return (
    <article
      className={`project-detail${isPost ? ' project-detail--post' : ''}`}
    >
      <a href={back.href} className='link project-detail__back'>
        <ArrowBackIcon fontSize='small' />
        {back.label}
      </a>

      <header className='project-detail__header'>
        <h1 className='project-detail__title'>{project.name}</h1>

        {project.subtitle || project.description ? (
          <p className='project-detail__description'>
            <InlineMarkdown>
              {project.subtitle || project.description}
            </InlineMarkdown>
          </p>
        ) : null}

        {project.period || project.date ? (
          <p className='project-detail__period'>
            {project.period || project.date}
          </p>
        ) : null}

        {/* 태그를 누르면 그 태그로 걸러진 블로그 목록으로 간다. */}
        <TagLinks items={project.tags} className='project-detail__tags' />
        <TagLinks items={project.stack} className='project-detail__tags' />

        <EntryLinks links={project.links} />
      </header>

      <div className='project-detail__content'>
        <BlockMarkdown>{project.content}</BlockMarkdown>
      </div>

      {/* 글의 끝을 분명하게 닫는다. 본문이 흐지부지 끝나면 독자는
          끝난 것인지 잘린 것인지 알 수 없다. */}
      <footer className='project-detail__footer'>
        {isPost && (prev || next) ? (
          <nav className='project-detail__adjacent' aria-label='이웃 글'>
            {prev ? (
              <a
                href={`#/posts/${prev.slug}`}
                className='project-detail__adjacent-link'
              >
                <span className='project-detail__adjacent-label'>
                  ← 이전 글
                </span>
                {prev.name}
              </a>
            ) : (
              <span />
            )}

            {next ? (
              <a
                href={`#/posts/${next.slug}`}
                className='project-detail__adjacent-link project-detail__adjacent-link--next'
              >
                <span className='project-detail__adjacent-label'>
                  다음 글 →
                </span>
                {next.name}
              </a>
            ) : (
              <span />
            )}
          </nav>
        ) : null}

        <a
          href={back.href}
          className='link project-detail__back project-detail__back--bottom'
        >
          <ArrowBackIcon fontSize='small' />
          {back.label}
        </a>
      </footer>
    </article>
  )
}

export default ProjectDetail
